('landing.hero.eyebrow', 'en-US', 'Shift Scheduling', 'Small uppercase eyebrow above main hero headline on landing page.'),
('landing.hero.eyebrow', 'da', 'Vagtplanlægning', 'Lille overlinje over hovedoverskriften i hero-sektionen.'),
