    ('employer_signup.error.submit_failed', 'Kunne ikke oprette forespørgslen lige nu. Prøv igen om et øjeblik.', 'Could not create the request right now. Please try again in a moment.', 'Generic submit failure message for employer signup form.'),
    ('employer_signup.error.network', 'Netværksfejl. Tjek forbindelsen og prøv igen.', 'Network error. Check your connection and try again.', 'Network error message for employer signup form submission.'),
    ('employer_signup.success.basic', 'Tak! Vi har oprettet din anmodning ({ticketId}). Download-trinnet kobles på snart.', 'Thanks! We created your request ({ticketId}). The download step will be connected soon.', 'Success message template after Basic submission; includes {ticketId}.'),
    ('employer_signup.success.other', 'Tak! Vi har modtaget din oprettelse ({ticketId}). Vi kontakter dig hurtigst muligt.', 'Thanks! We received your signup ({ticketId}). We will contact you as soon as possible.', 'Success message template after non-Basic submission; includes {ticketId}.')
  ) as v(translation_key, da_text, en_text, context_description)
)
insert into public.ui_translations (translation_key, language_code, text_value, context_description)
select
  k.translation_key,
  l.language_code,
  case
    when l.language_code = 'da' then k.da_text
    else k.en_text
  end as text_value,
  k.context_description
from employer_signup_keys k
cross join public.languages l
on conflict (translation_key, language_code) do update set
  text_value = excluded.text_value,
  context_description = excluded.context_description;

